INSERT INTO "lez_zone" ("id", "name", "description", "coordinates", "active", "created_at", "updated_at") VALUES ('zone-ring-road-1', 'Vùng phát thải thấp Vành đai 1', 'Vùng phát thải thấp Vành đai 1 — theo lộ trình triển khai Chỉ thị số 20/CT-TTg. Phạm vi áp dụng: toàn bộ các tuyến đường, phố nằm phía trong vòng giới hạn của Vành đai 1, bao quanh bởi các trục đường chính: Trần Khát Chân – Đại Cồ Việt – Xã Đàn; Ô Chợ Dừa – Hoàng Cầu (nhánh phụ); Voi Phục – Kim Mã – Giảng Võ; Nguyễn Khoái (đê ven sông). Quy định (hiệu lực từ 01/07/2026): cấm hoàn toàn xe mô tô, xe gắn máy (hai bánh) sử dụng nhiên liệu hóa thạch (xăng, dầu) — áp dụng 24/7; xe máy điện, xe đạp điện, các phương tiện năng lượng xanh và giao thông công cộng (xe buýt, tàu điện) được phép lưu thông; ô tô xăng/dầu chưa bị cấm hoàn toàn nhưng chịu mức phí trước bạ, phí cấp biển số và phí trông giữ cao hơn tại khu vực trung tâm theo lộ trình tăng dần từ Quý III/2025. Thành phố đang thực hiện thí điểm cuốn chiếu bắt đầu từ một số vùng lõi thuộc quận Hoàn Kiếm.', '[[21.036, 105.8527], [21.014, 105.853], [21.00858, 105.85141], [21.00753, 105.84156], [21.00797, 105.83991], [21.00894, 105.83864], [21.01501, 105.83326], [21.01806, 105.82971], [21.01881, 105.82961], [21.0209, 105.82563], [21.01666, 105.82339], [21.01638, 105.8211], [21.01378, 105.81889], [21.0165, 105.82], [21.0212, 105.821], [21.0234, 105.81989], [21.03136, 105.82973], [21.03217, 105.83], [21.0324, 105.82885], [21.03055, 105.81726], [21.0345, 105.815], [21.03048, 105.81279], [21.04343, 105.81682], [21.0436, 105.8197], [21.04291, 105.8237], [21.04092, 105.82792], [21.0427, 105.83272], [21.04271, 105.83585], [21.0403, 105.8476], [21.0399, 105.84718], [21.0407, 105.84993]]', true, '2026-10-03 01:17:38.273026+00:00'::timestamptz, '2026-10-03 05:41:30.895753+00:00'::timestamptz);
INSERT INTO "policy_rule" ("id", "zone_id", "mode_id", "restriction_type", "condition", "start_time", "end_time", "days", "active", "created_at") VALUES ('a6e3547b9a4d4b309a23a0af6e5c54fd', 'zone-ring-road-1', 'gasoline_motorbike', 'banned', 'Cấm hoàn toàn xe mô tô, xe gắn máy (hai bánh) sử dụng nhiên liệu hóa thạch (xăng, dầu) trong phạm vi Vành đai 1 — 24/7, có hiệu lực từ 01/07/2026 theo Chỉ thị số 20/CT-TTg.', '00:00', '23:59', 'Mon,Tue,Wed,Thu,Fri,Sat,Sun', true, '2026-10-03 05:42:48.894111+00:00'::timestamptz);
INSERT INTO "policy_rule" ("id", "zone_id", "mode_id", "restriction_type", "condition", "start_time", "end_time", "days", "active", "created_at") VALUES ('e3d02e0efd464affb7ef94a92244adf3', 'zone-ring-road-1', 'private_car', 'conditional', 'Ô tô chạy xăng/dầu chưa bị cấm hoàn toàn ở giai đoạn Vành đai 1, nhưng chịu mức phí trước bạ, phí cấp biển số và phí trông giữ cao hơn tại khu vực trung tâm theo lộ trình tăng dần từ Quý III/2025.', '00:00', '23:59', 'Mon,Tue,Wed,Thu,Fri,Sat,Sun', true, '2026-10-03 05:42:48.894443+00:00'::timestamptz);
